//! `iwbtg script api-docs` (docs/decisions/0001-script-language.md, Tooling for agents).
//!
//! Generates `docs/format/script-api.md` and the Rhai language-server stubs
//! `docs/format/script/iws.d.rhai` from the functions registered on the real engine
//! (`Iws::rhai_engine`, Rhai metadata), so the docs cannot drift from the code. A test fails when
//! the committed files differ from the generated ones.

use std::path::Path;

use iwbtg_sim::rules::NumRules;
use iwbtg_sim::script::host::Iws;
use serde_json::Value;

use crate::trace_cmd::ToolError;

/// Where the generated files go, relative to the docs folder.
pub const MD_PATH: &str = "format/script-api.md";
/// The language-server stubs, relative to the docs folder.
pub const STUBS_PATH: &str = "format/script/iws.d.rhai";

/// One registered function, with Rust type names turned into script type names.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Func {
    name: String,
    params: Vec<String>,
    ret: String,
    /// The Rust function returns a `Result`: a bad argument or state is a script error.
    fails: bool,
}

/// `crates/tools` -> the docs folder of the workspace.
pub fn default_docs_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs")
}

/// The type as a script author sees it.
fn script_type(rust: &str) -> String {
    let t = rust.trim().trim_start_matches("&mut ").trim_start_matches('&');
    let last = t.rsplit("::").next().unwrap_or(t);
    match last {
        "f64" => "float",
        "i64" => "int",
        "bool" => "bool",
        "()" => "()",
        "string" | "ImmutableString" => "string",
        "array" | "Array" => "array",
        "map" | "Map" => "map",
        "Dynamic" => "?",
        "Inst" | "Instance" => "Instance",
        other => other,
    }
    .to_owned()
}

/// `core::result::Result<T,alloc::boxed::Box<...>>` -> `(T, true)`; anything else -> `(it, false)`.
fn split_result(ret: &str) -> (String, bool) {
    match ret
        .strip_prefix("core::result::Result<")
        .and_then(|r| r.strip_suffix(",alloc::boxed::Box<rhai::types::error::EvalAltResult>>"))
    {
        Some(inner) => (script_type(inner), true),
        None => (script_type(ret), false),
    }
}

fn functions() -> Result<Vec<Func>, ToolError> {
    let iws = Iws::new(NumRules::default());
    let json = iws
        .rhai_engine()
        .gen_fn_metadata_to_json(false)
        .map_err(|e| ToolError::Message(format!("rhai metadata: {e}")))?;
    let v: Value =
        serde_json::from_str(&json).map_err(|e| ToolError::Message(format!("rhai metadata: {e}")))?;
    let mut out: Vec<Func> = v["functions"]
        .as_array()
        .ok_or_else(|| ToolError::Message("rhai metadata has no functions".into()))?
        .iter()
        .map(|f| {
            let (ret, fails) = split_result(f["returnType"].as_str().unwrap_or("()"));
            Func {
                name: f["name"].as_str().unwrap_or("").to_owned(),
                params: f["params"]
                    .as_array()
                    .map(|ps| {
                        ps.iter()
                            .map(|p| script_type(p["type"].as_str().unwrap_or("?")))
                            .collect()
                    })
                    .unwrap_or_default(),
                ret,
                fails,
            }
        })
        .collect();
    out.sort();
    out.dedup();
    Ok(out)
}

fn is_operator(name: &str) -> bool {
    !name.starts_with(|c: char| c.is_ascii_alphabetic() || c == '_')
}

/// `fn name(_: a, _: b) -> r;` as a Rhai definition file writes it.
fn stub_line(f: &Func) -> String {
    let (kw, name) = if let Some(p) = f.name.strip_prefix("get$") {
        ("fn get", p.to_owned())
    } else if let Some(p) = f.name.strip_prefix("set$") {
        ("fn set", p.to_owned())
    } else if f.name.starts_with("index$") {
        ("fn", f.name.clone())
    } else if is_operator(&f.name) {
        ("op", f.name.clone())
    } else {
        ("fn", f.name.clone())
    };
    let params: Vec<String> = f.params.iter().map(|p| format!("_: {p}")).collect();
    format!("{kw} {name}({}) -> {};", params.join(", "), f.ret)
}

fn stubs(funcs: &[Func]) -> String {
    let mut s = String::from(
        "// Generated by `iwbtg script api-docs` from the functions registered on the IWS engine.\n\
         // Do not edit; docs/format/script-api.md explains each group.\n\
         module static;\n",
    );
    for f in funcs {
        s.push('\n');
        s.push_str(&stub_line(f));
        s.push('\n');
    }
    s
}

/// The readable signature: `name(float, float) -> float`, with `!` after the arrow when the
/// call can fail.
fn md_sig(f: &Func) -> String {
    let fail = if f.fails { " (can fail)" } else { "" };
    format!("`{}({}) -> {}`{fail}", f.name, f.params.join(", "), f.ret)
}

const INTRO: &str = "# Script API (generated)\n\n\
Generated by `iwbtg script api-docs` from the functions registered on the IWS engine (Rhai metadata); do not edit by hand. A test (`cargo test -p iwbtg-tools committed_docs`) fails when this file or `script/iws.d.rhai` is stale. The language and its limits are in [0001](../decisions/0001-script-language.md); the first-version overview is in [architecture](../architecture.md#script-api-first-version).\n\n\
`script/iws.d.rhai` holds the same list as Rhai definitions for the Rhai language server. Types: `float` is every number a script sees (the engine uses `only_i64`, so integers exist, but API numbers are floats), `int`, `string`, `array`, `map`, `Instance` (a handle to an object instance) and `?` (any value). \"can fail\" means a bad argument or state stops the script with an error.\n\n\
## Porting from GML\n\n\
- **Division.** `/` on two integers gives a FLOAT, as in GML. Use `div` and `mod` for GML `div` and `mod`.\n\
- **Comparisons.** `==`, `<` and the rest on floats are exact IEEE. GML compares with the runner's epsilon: use `gm_eq`, `gm_ne`, `gm_lt`, `gm_le`, `gm_gt`, `gm_ge` where the original compares reals. The load check warns about a raw float `==`.\n\
- **Truthiness.** A number is not a condition. Use `gm_bool(x)` for GML's `x > 0.5` rule.\n\
- **`with`.** There is none. `instances(kind_or_group)` returns an array that is a snapshot at call time; loop over it.\n\
- **Implicit instance variables.** Variables are not implicit: write `this.hp`, not `hp`. An unset read is an error.\n\
- **Draw logic.** Scripts do not draw; see 0001 for `late()`.\n\n";

fn markdown(funcs: &[Func]) -> String {
    let mut props: std::collections::BTreeMap<String, (String, bool, bool)> = Default::default();
    for f in funcs {
        for (prefix, w) in [("get$", false), ("set$", true)] {
            if let Some(n) = f.name.strip_prefix(prefix) {
                let e = props.entry(n.to_owned()).or_insert((String::new(), false, false));
                if w {
                    e.2 = true;
                    if e.0.is_empty() {
                        e.0 = f.params.get(1).cloned().unwrap_or_default();
                    }
                } else {
                    e.1 = true;
                    e.0.clone_from(&f.ret);
                }
            }
        }
    }
    let rest: Vec<&Func> = funcs
        .iter()
        .filter(|f| !f.name.starts_with("get$") && !f.name.starts_with("set$"))
        .collect();
    let mut s = String::from(INTRO);
    s.push_str("## Instance properties\n\nRead with `i.name`, write with `i.name = v` where listed read and write.\n\n| Property | Type | Access |\n|---|---|---|\n");
    for (n, (t, r, w)) in &props {
        let acc = match (r, w) {
            (true, true) => "read, write",
            (true, false) => "read only",
            _ => "write only",
        };
        s.push_str(&format!("| `{n}` | {t} | {acc} |\n"));
    }
    s.push_str("\n## Operators\n\n");
    for f in rest
        .iter()
        .filter(|f| is_operator(&f.name) && !f.name.starts_with("index$"))
    {
        s.push_str(&format!("- {}\n", md_sig(f)));
    }
    s.push_str("\n## Functions\n\n");
    for f in rest
        .iter()
        .filter(|f| !is_operator(&f.name) || f.name.starts_with("index$"))
    {
        s.push_str(&format!("- {}\n", md_sig(f)));
    }
    s
}

/// The generated files as `(path relative to docs/, text)`.
pub fn generate() -> Result<Vec<(&'static str, String)>, ToolError> {
    let funcs = functions()?;
    Ok(vec![(MD_PATH, markdown(&funcs)), (STUBS_PATH, stubs(&funcs))])
}

/// `iwbtg script api-docs [--check]`: writes the files under `docs`, or with `check` compares and
/// exits 1 when they differ.
pub fn main(docs: &Path, check: bool) -> Result<bool, ToolError> {
    let mut ok = true;
    for (rel, text) in generate()? {
        let path = docs.join(rel);
        let on_disk = std::fs::read_to_string(&path)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        if on_disk == text {
            println!("up to date: {rel}");
        } else if check {
            println!("stale: {rel} (run `iwbtg script api-docs`)");
            ok = false;
        } else {
            if let Some(dir) = path.parent() {
                std::fs::create_dir_all(dir)
                    .map_err(|e| ToolError::Message(format!("{}: {e}", dir.display())))?;
            }
            std::fs::write(&path, text.as_bytes())
                .map_err(|e| ToolError::Message(format!("{}: {e}", path.display())))?;
            println!("wrote: {rel}");
        }
    }
    Ok(ok)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn types_and_results_are_cleaned() {
        assert_eq!(script_type("&mut iwbtg_sim::script::inst::Inst"), "Instance");
        assert_eq!(script_type("types::dynamic::Dynamic"), "?");
        let (t, fails) =
            split_result("core::result::Result<f64,alloc::boxed::Box<rhai::types::error::EvalAltResult>>");
        assert_eq!((t.as_str(), fails), ("float", true));
        assert_eq!(split_result("bool"), ("bool".to_owned(), false));
    }

    #[test]
    fn the_committed_docs_match_the_registered_api() {
        let docs = default_docs_dir();
        for (rel, text) in generate().unwrap() {
            let on_disk = std::fs::read_to_string(docs.join(rel))
                .unwrap_or_default()
                .replace("\r\n", "\n");
            assert!(
                on_disk == text,
                "{rel} is stale: run `cargo run -p iwbtg-tools -- script api-docs` and commit the result"
            );
        }
    }
}
